import { integer, pgTable, text, uuid } from "drizzle-orm/pg-core";

export const tasks = pgTable("tasks", {
  id: integer("id").primaryKey(),
  title: text("title").notNull(),
  assignee: text("assignee"),
});

// One row per recorded signup; the id is generated by PostgreSQL.
export const signups = pgTable("signups", {
  id: uuid("id").primaryKey().defaultRandom(),
  accountId: integer("account_id").notNull(),
  requestId: text("request_id").notNull(),
});

// The idempotent variant keys the row by the client's request id.
export const signupRequests = pgTable("signup_requests", {
  requestId: text("request_id").primaryKey(),
  accountId: integer("account_id").notNull(),
});

// Page views, counted with an upsert.
export const views = pgTable("views", {
  id: integer("id").primaryKey(),
  hits: integer("hits").notNull(),
});

// Handles are reserved with an upsert that takes the handle over.
export const handles = pgTable("handles", {
  handle: text("handle").primaryKey(),
  owner: text("owner"),
});
